mapper.select:
SELECT s.*
FROM mis_stock s

    s.del_flag = '0'

    AND (
    (s.shelf_id IS NOT NULL AND s.shelf_id != '')
    OR (s.area_id IS NOT NULL AND s.area_id != '')
    )


        AND s.warehouse_id = #{stock.warehouseId}


        AND s.area_id = #{stock.areaId}


        AND s.shelf_id = #{stock.shelfId}


        AND s.location_id = #{stock.locationId}


        AND s.goods_name LIKE CONCAT('%', #{stock.goodsName}, '%')


        AND s.batch_no = #{stock.batchNo}


        AND s.goods_type = #{stock.goodsType}


        AND s.is_product = #{stock.isProduct}


    AND s.quantity > 0

ORDER BY s.create_time DESC
